aif = date(2026,2,3)
# Cenários de decadência sob cada leitura teórica (valores CDA por período)
v = {"3T/2020":268000,"4T/2020":241000,"1T/2021":302000,"2T/2021":289000}
def dec(p):
    lims = {"3T/2020":{ "T1 trimestral (173 I, venc. out/2020)": date(2025,12,31),
