for p in v: dec(p)
cen = {"Correta (Tema163/555, trimestre)": 268000+241000,
       "FG anual (regra mesma)": 241000,
       "Fazenda (173 I a todos, lógica dela)": 268000}
for k,x in cen.items():
    print(f"{k}: decaído {x:>9,} | exequendo {1100000-x:>9,}")
print("Mínimo decaído em qualquer hipótese:", min(cen.values()))
